// Collect the form answers and give the screenshot a fixed name ("screenshot")
const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});

if (binaryKeys.length === 0) {
  throw new Error('No screenshot was uploaded.');
}

const screenshot = item.binary[binaryKeys[0]];
if (!(screenshot.mimeType || '').startsWith('image/')) {
  throw new Error(`The uploaded file is not an image (${screenshot.mimeType}).`);
}

const form = item.json;
const clean = (value) => (value || '').toString().trim();

return [{
  json: {
    user_notes: clean(form['What were you doing?']),
    environment: clean(form['Environment / Page URL']),
    error_logs: clean(form['Error Logs']),
    submitted_at: form.submittedAt || new Date().toISOString(),
  },
  binary: { screenshot },
}];

