// Turn the AI output into Jira wiki markup and the fields the Jira node needs
const bug = $input.first().json.output;
const input = $('Normalize Input').first().json;

const list = (items, bullet) =>
  (items || []).filter(Boolean).map((text) => `${bullet} ${text}`).join('\n');

const env = bug.environment || {};
const envLines = [
  ['Browser', env.browser],
  ['OS', env.os],
  ['URL', env.url],
  ['App version', env.app_version],
]
  .filter(([, value]) => value && value !== 'Unknown')
  .map(([name, value]) => `* *${name}:* ${value}`)
  .join('\n');

// Keep very long logs from hitting Jira's description size limit
const MAX_LOG_CHARS = 10000;
let logs = input.error_logs;
if (logs.length > MAX_LOG_CHARS) {
  logs = logs.slice(0, MAX_LOG_CHARS) + '\n... (truncated)';
}

const sections = [
  'h3. Description', bug.description,
  'h3. Steps to Reproduce', list(bug.steps_to_reproduce, '#'),
  'h3. Expected Result', bug.expected_result,
  'h3. Actual Result', bug.actual_result,
  'h3. Visual Observations', list(bug.visual_observations, '*') || 'None noted.',
  'h3. Environment', envLines || (input.environment || 'Not visible in the screenshot.'),
  'h3. Severity', bug.severity,
];
if (bug.error_summary) sections.push('h3. Error Summary', bug.error_summary);
if (logs) sections.push('h3. Error Logs', '{code}\n' + logs + '\n{code}');
if (input.user_notes) sections.push('h3. Tester Notes', input.user_notes);
sections.push(
  '----',
  '_Drafted by the n8n Screenshot-to-Bug-Reporter from an uploaded screenshot. Please review before triage. Screenshot attached._',
);

// Default Jira Cloud priority IDs
const PRIORITY_IDS = { Highest: '1', High: '2', Medium: '3', Low: '4', Lowest: '5' };

// Jira labels cannot contain spaces
const labels = ['ai-generated', 'screenshot-bug', ...(bug.labels || [])]
  .map((label) => String(label).toLowerCase().trim().replace(/\s+/g, '-'))
  .filter(Boolean);

return [{
  json: {
    summary: (bug.summary || 'Bug reported from screenshot').slice(0, 250),
    description: sections.join('\n\n'),
    priority_id: PRIORITY_IDS[bug.priority] || '3',
    labels: [...new Set(labels)],
  },
}];

// The Jira create output has no binary data, so bring the screenshot back
const created = $input.first().json;
const upload = $('Normalize Input').first();
const baseUrl = created.self.split('/rest/')[0];

return [{
  json: {
    key: created.key,
    url: `${baseUrl}/browse/${created.key}`,
  },
  binary: { screenshot: upload.binary.screenshot },
}];

